-- Fix missing playercreateinfo rows for race 98 (Horde Drakonid) and race 79 (Arakkoa).
-- Race 98 uses Orc starting coords (map 1, Durotar).
-- Race 79 uses Night Elf starting coords (map 1, Teldrassil).
-- DELETE first so this is idempotent if rows were hand-inserted.
START TRANSACTION;

DELETE FROM `playercreateinfo` WHERE `race` IN (98, 79);

COMMIT;
